(6637719, 989987, 94265, '<td valign="top">Shame about the crop through the hand but a very nice shot otherwise, good exposure, love his wee coat and his expression.</td>', 'Shame about the crop through the hand but a very nice shot otherwise, good exposure, love his wee coat and his expression.', '2012-01-07 13:58:49.000000', NULL, 1),
