(6637877, 990401, 76335, '<td valign="top">Simple and up close. I like that. Some might say the flash is a bit harsh, but sometimes that''s an okay aesthetic for an impromptu sort of portrait. I like the background.</td>', 'Simple and up close. I like that. Some might say the flash is a bit harsh, but sometimes that''s an okay aesthetic for an impromptu sort of portrait. I like the background.', '2012-01-07 18:18:53.000000', NULL, 1),
(6637878, 990801, 76335, '<td valign="top">This is different. Initially I was put off by the reflection in the glasses. But I do like quirky. So I''m torn.</td>', 'This is different. Initially I was put off by the reflection in the glasses. But I do like quirky. So I''m torn.', '2012-01-07 18:20:16.000000', NULL, 1),
(6637879, 989904, 76335, '<td valign="top">Warm and casual. Sincerely ours.</td>', 'Warm and casual. Sincerely ours.', '2012-01-07 18:21:24.000000', NULL, 1),
